
package com.camtv.tv; import android.app.Notification; import android.app.NotificationChannel; import android.app.NotificationManager; import android.app.PendingIntent; import android.app.Service; import android.content.Intent; import android.os.Build; import android.os.IBinder; public class MonitorService extends Service { @Override public void onCreate() { super.onCreate(); startForegroundService(); } void startForegroundService() { String channelId = "camtv_monitor"; if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) { NotificationChannel channel = new NotificationChannel( channelId, "مراقبة الكاميرات", NotificationManager.IMPORTANCE_LOW ); NotificationManager manager = getSystemService(NotificationManager.class); if (manager != null) { manager.createNotificationChannel(channel); } } Intent intent = new Intent(this, MainActivity.class); PendingIntent pending = PendingIntent.getActivity( this, 0, intent, PendingIntent.FLAG_IMMUTABLE ); Notification notification = new Notification.Builder(this, channelId) .setContentTitle("CamTV شغال بالخلفية") .setContentText("المراقبة شغالة - 8 كاميرات") .setSmallIcon(android.R.drawable.ic_menu_camera) .setContentIntent(pending) .build(); startForeground(1, notification); } @Override public int onStartCommand(Intent intent, int flags, int startId) { startForegroundService(); return START_STICKY; } @Override public IBinder onBind(Intent intent) { return null; } }
